const defaults={
 name:"Daffa Ubaydillah",tag:"Kreator • Pelajar • Freelancer",
 about:"Halo, saya Daffa Ubaydillah. Selamat datang di portfolio pribadi saya. Di sini kamu bisa mengenal saya, melihat foto, menemukan tautan penting, dan menjelajahi proyek yang pernah saya buat.",
 heroImage:"data:image/jpeg;base64,"+EMBEDDED_HERO,
 links:[{title:"YouTube",desc:"Ikuti aktivitas saya",url:"https://youtube.com/@KINGDAFFZ-n3x",symbol:"◎"},{title:"TikTok",desc:"Video dan konten saya",url:"https://www.tiktok.com/@daffaubaydillah95",symbol:"♪"},{title:"WhatsApp",desc:"Hubungi saya",url:"https://wa.me/6285151833180",symbol:"✆"}],
 photos:["images/galeri-1.jpg","images/galeri-2.jpg","images/galeri-3.jpg"],
 projects:[{title:"Belajar SI",desc:"Proyek website pembelajaran Sistem Informasi.",category:"WEB",image:"images/proyek-1.jpg",url:"https://belajar-si.onrender.com"},{title:"My Life Dafzz",desc:"Website personal tentang kehidupan dan aktivitas saya.",category:"PERSONAL",image:"images/proyek-2.jpg",url:"https://my-life-dafzz.onrender.com"},{title:"Hollow Dafzz",desc:"Proyek kreatif digital karya saya.",category:"CREATIVE",image:"images/proyek-3.jpg",url:"https://hollow-dafzz.onrender.com"}]
};
let data;try{data=Object.assign(structuredClone(defaults),JSON.parse(localStorage.getItem('myPortfolio')||'{}'))}catch(e){data=JSON.parse(JSON.stringify(defaults))}
const $=s=>document.querySelector(s);let current='';
const safe=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function toast(s){let t=$('#toast');t.textContent=s;t.classList.add('show');setTimeout(()=>t.classList.remove('show'),2600)}
function persist(msg='Perubahan berhasil disimpan di perangkat ini.'){try{localStorage.setItem('myPortfolio',JSON.stringify(data));render();toast(msg)}catch(e){toast('Penyimpanan penuh. Kurangi ukuran/jumlah foto lalu coba lagi.')}}
function render(){
 $('#heroName').textContent=data.name;$('#aboutName').textContent=data.name;$('#heroTag').textContent=data.tag;$('#aboutText').textContent=data.about;$('#heroImage').src=(data.heroImage && data.heroImage.startsWith('data:'))?data.heroImage:('data:image/jpeg;base64,'+EMBEDDED_HERO);
 const touchLayer=$('#heroTouchImage'); if(touchLayer) touchLayer.src='data:image/jpeg;base64,'+EMBEDDED_TOUCH;$('#year').textContent=new Date().getFullYear();
 $('#linkList').innerHTML=(data.links||[]).map(x=>`<a class="link-card" href="${safe(x.url)}" target="_blank" rel="noopener"><span class="symbol">${safe(x.symbol||'↗')}</span><span class="arrow">↗</span><h3>${safe(x.title)}</h3><p>${safe(x.desc)}</p></a>`).join('');
 $('#photoList').innerHTML=(data.photos||[]).map((x,i)=>`<button type="button" class="photo-card" data-view-image="${i}" aria-label="Lihat foto ${i+1}"><img src="${safe(x)}" alt="Foto ${i+1}" loading="lazy"><span class="photo-hint">Lihat foto ↗</span></button>`).join('');
 $('#projectList').innerHTML=(data.projects||[]).map(x=>`<a class="project-card" href="${safe(x.url||'#')}" target="_blank" rel="noopener"><img src="${safe(x.image)}" alt="${safe(x.title)}" loading="lazy"><div class="project-info"><small>${safe(x.category)}</small><h3>${safe(x.title)}</h3><p>${safe(x.desc)}</p></div></a>`).join('');  typeHeroName(data.name);
  observePremiumReveal();
}

// Efek sentuh/kursor: foto kedua hanya tampak di bawah titik pointer.
(function bindHeroTouchReveal(){
 const area=document.getElementById('heroPhoto');
 if(!area)return;
 let hideTimer=null;
 const move=e=>{
   const r=area.getBoundingClientRect();
   const x=Math.max(0,Math.min(r.width,e.clientX-r.left));
   const y=Math.max(0,Math.min(r.height,e.clientY-r.top));
   area.style.setProperty('--touch-x',x+'px');
   area.style.setProperty('--touch-y',y+'px');
   area.classList.add('touch-active');
   clearTimeout(hideTimer);
   if(e.pointerType==='touch')hideTimer=setTimeout(()=>area.classList.remove('touch-active'),650);
 };
 area.addEventListener('pointerdown',move);
 area.addEventListener('pointermove',e=>{if(e.pointerType!=='touch'||e.buttons>0||e.pressure>0)move(e);else if(e.pointerType==='mouse')move(e)});
 area.addEventListener('pointerleave',()=>area.classList.remove('touch-active'));
 area.addEventListener('pointerup',e=>{if(e.pointerType==='touch'){clearTimeout(hideTimer);hideTimer=setTimeout(()=>area.classList.remove('touch-active'),650)}});
})();
function field(label,value,key,type='text'){return `<div class="field"><label>${label}</label><input type="${type}" data-key="${key}" value="${safe(value||'')}"></div>`}
function area(label,value,key){return `<div class="field"><label>${label}</label><textarea data-key="${key}">${safe(value||'')}</textarea></div>`}
function imageOptions(){return `<div class="editor-tools"><div class="field"><label>Potong / sesuaikan foto</label><select id="cropMode"><option value="contain">Asli (tanpa potong)</option><option value="square">Kotak 1:1</option><option value="portrait">Potret 4:5</option><option value="wide">Lebar 16:9</option></select></div><div class="field"><label><input type="checkbox" id="removeBg"> Hapus background polos (hasil terbaik untuk latar satu warna)</label></div><div class="field"><label>Tingkat hapus background: <span id="tolLabel">35</span></label><input id="bgTolerance" type="range" min="10" max="100" value="35"></div><small>Foto akan otomatis diperkecil agar tidak terlalu berat. Untuk hapus background AI yang rumit, gunakan gambar PNG transparan.</small></div>`}
function itemEditor(arr,type){return arr.map((x,i)=>`<div class="editor-item" data-index="${i}">${type==='links'?field('Nama link',x.title,'title')+field('Deskripsi',x.desc,'desc')+field('Alamat link (URL)',x.url,'url')+field('Simbol',x.symbol,'symbol'):type==='projects'?field('Nama proyek',x.title,'title')+field('Kategori',x.category,'category')+area('Deskripsi',x.desc,'desc')+field('Link proyek',x.url,'url')+field('URL gambar',x.image,'image')+`<div class="field"><label>Atau unggah gambar proyek</label><input type="file" accept="image/*" class="project-file" data-project-file="${i}"></div>`:`${field('URL foto',x,'photo')}<div class="field"><label>Ganti foto dari galeri</label><input type="file" accept="image/*" class="replace-photo" data-photo-file="${i}"></div>`}<div class="item-actions"><button type="button" class="move-up" ${i===0?'disabled':''}>↑ Naik</button><button type="button" class="move-down" ${i===arr.length-1?'disabled':''}>↓ Turun</button><button type="button" class="remove-item">Hapus</button></div></div>`).join('')}
function openEditor(type){current=type;let html='',title='';
 if(type==='profile'){title='Edit Profil';html=field('Nama kamu',data.name,'name')+field('Tulisan singkat',data.tag,'tag')+area('Tentang saya',data.about,'about')+field('URL foto utama',data.heroImage,'heroImage')+`<div class="field"><label>Atau pilih foto utama dari HP</label><input type="file" id="heroUpload" accept="image/*"></div>`+imageOptions()}
 if(type==='links'){title='Ubah Link';html=itemEditor(data.links,'links')+`<button class="add-btn" id="addItem">＋ Tambah Link</button>`}
 if(type==='photos'){title='Ubah Foto';html=imageOptions()+`<div class="field"><label>Pilih foto dari galeri HP (bisa beberapa)</label><input type="file" id="photoUpload" accept="image/*" multiple></div>`+itemEditor(data.photos,'photos')+`<button class="add-btn" id="addItem">＋ Tambah URL Foto</button>`}
 if(type==='projects'){title='Ubah Proyek';html=imageOptions()+itemEditor(data.projects,'projects')+`<button class="add-btn" id="addItem">＋ Tambah Proyek</button>`}
 $('#editorTitle').textContent=title;$('#editorBody').innerHTML=html;$('#editor').classList.add('open');$('#editor').setAttribute('aria-hidden','false');
 $('#bgTolerance')?.addEventListener('input',e=>$('#tolLabel').textContent=e.target.value);
 $('#addItem')?.addEventListener('click',()=>{if(type==='links')data.links.push({title:'Link baru',desc:'Deskripsi link',url:'https://',symbol:'↗'});if(type==='photos')data.photos.push('');if(type==='projects')data.projects.push({title:'Proyek baru',desc:'Deskripsi proyek',category:'PROJECT',image:'',url:'#'});openEditor(type)});
 $('#editorBody').querySelectorAll('.remove-item').forEach(b=>b.addEventListener('click',()=>{let i=+b.closest('.editor-item').dataset.index;(type==='links'?data.links:type==='photos'?data.photos:data.projects).splice(i,1);openEditor(type)}));
 $('#editorBody').querySelectorAll('.move-up,.move-down').forEach(b=>b.addEventListener('click',()=>{let el=b.closest('.editor-item'),i=+el.dataset.index,arr=type==='links'?data.links:type==='photos'?data.photos:data.projects,j=i+(b.classList.contains('move-up')?-1:1);if(j<0||j>=arr.length)return;[arr[i],arr[j]]=[arr[j],arr[i]];openEditor(type)}));
}
function closeEditor(){$('#editor').classList.remove('open');$('#editor').setAttribute('aria-hidden','true')}
function fileToData(file,mode='contain',removeBg=false,tolerance=35){return new Promise((resolve,reject)=>{const reader=new FileReader();reader.onerror=reject;reader.onload=()=>{const img=new Image();img.onerror=reject;img.onload=()=>{let sw=img.width,sh=img.height,max=1500;if(sw>max||sh>max){let k=max/Math.max(sw,sh);sw=Math.round(sw*k);sh=Math.round(sh*k)}let canvas=document.createElement('canvas'),ctx=canvas.getContext('2d',{willReadFrequently:true});let ratio=mode==='square'?1:mode==='portrait'?4/5:mode==='wide'?16/9:null,cw=sw,ch=sh,sx=0,sy=0;if(ratio){if(sw/sh>ratio){cw=Math.round(sh*ratio);sx=Math.round((sw-cw)/2)}else{ch=Math.round(sw/ratio);sy=Math.round((sh-ch)/2)}}canvas.width=cw;canvas.height=ch;ctx.drawImage(img,sx,sy,cw,ch,0,0,cw,ch);
 if(removeBg){let im=ctx.getImageData(0,0,cw,ch),p=im.data,seen=new Uint8Array(cw*ch),stack=[];const add=(x,y)=>{if(x<0||y<0||x>=cw||y>=ch)return;let n=y*cw+x;if(!seen[n]){seen[n]=1;stack.push(n)}};for(let x=0;x<cw;x++){add(x,0);add(x,ch-1)}for(let y=0;y<ch;y++){add(0,y);add(cw-1,y)}let corners=[[0,0],[cw-1,0],[0,ch-1],[cw-1,ch-1]],base=[0,0,0];for(let [x,y] of corners){let n=(y*cw+x)*4;base[0]+=p[n];base[1]+=p[n+1];base[2]+=p[n+2]}base=base.map(v=>v/4);let lim=Number(tolerance)*2.4;while(stack.length){let n=stack.pop(),k=n*4,dist=Math.sqrt((p[k]-base[0])**2+(p[k+1]-base[1])**2+(p[k+2]-base[2])**2);if(dist<lim){p[k+3]=0;let x=n%cw,y=Math.floor(n/cw);add(x+1,y);add(x-1,y);add(x,y+1);add(x,y-1)}}ctx.putImageData(im,0,0)}
 resolve(removeBg?canvas.toDataURL('image/png'):canvas.toDataURL('image/jpeg',.84));};img.src=reader.result};reader.readAsDataURL(file)})}
function requestEdit(type){const pass=prompt('Masukkan sandi untuk Mode Edit:');if(pass===null)return;const expected=document.querySelector('meta[name="edit-password"]')?.content||'';if(pass===expected)openEditor(type);else toast('Sandi salah.')}
