/* ================= PREMIUM MINIMALIS EFFECTS ================= */
let premiumTypingTimer = null;
let premiumRevealObserver = null;
function typeHeroName(value) {
  const target = document.getElementById('heroName');
  if (!target) return;
  if (premiumTypingTimer) clearInterval(premiumTypingTimer);
  const textValue = String(value ?? '');
  if (window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches) {
    target.textContent = textValue;
    return;
  }
  target.textContent = '';
  let index = 0;
  premiumTypingTimer = setInterval(() => {
    target.textContent = textValue.slice(0, ++index);
    if (index >= textValue.length) clearInterval(premiumTypingTimer);
  }, 72);
}

function observePremiumReveal() {
  const nodes = document.querySelectorAll('.section, .section-head, .intro > div, .link-card, .photo-card, .project-card, footer');
  if (!('IntersectionObserver' in window)) {
    nodes.forEach(node => node.classList.add('is-visible'));
    return;
  }
  if (!premiumRevealObserver) {
    premiumRevealObserver = new IntersectionObserver(entries => {
      entries.forEach(entry => {
        if (entry.isIntersecting) {
          entry.target.classList.add('is-visible');
          premiumRevealObserver.unobserve(entry.target);
        }
      });
    }, { threshold: 0.12, rootMargin: '0px 0px -35px 0px' });
  }
  nodes.forEach((node, index) => {
    if (node.dataset.premiumRevealBound === '1') return;
    node.dataset.premiumRevealBound = '1';
    node.classList.add('reveal-item');
    if (node.matches('.link-card, .photo-card, .project-card')) {
      node.style.setProperty('--reveal-delay', (index % 3) * 75 + 'ms');
    }
    premiumRevealObserver.observe(node);
  });
}

(function initPremiumParticles() {
  if (window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches) return;
  const layer = document.createElement('div');
  layer.className = 'premium-particles';
  layer.setAttribute('aria-hidden', 'true');
  const count = window.innerWidth < 600 ? 11 : 19;
  for (let i = 0; i < count; i++) {
    const dot = document.createElement('span');
    dot.style.setProperty('--px', (Math.random() * 100).toFixed(2) + '%');
    dot.style.setProperty('--ps', (2 + Math.random() * 3).toFixed(1) + 'px');
    dot.style.setProperty('--pd', (17 + Math.random() * 17).toFixed(1) + 's');
    dot.style.setProperty('--pdelay', (-Math.random() * 28).toFixed(1) + 's');
    dot.style.setProperty('--px-drift', ((Math.random() - .5) * 100).toFixed(1) + 'px');
    layer.appendChild(dot);
  }
  document.body.prepend(layer);
})();

(function initPremiumCursorGlow() {
  if (!window.matchMedia || !window.matchMedia('(hover:hover) and (pointer:fine)').matches) return;
  const glow = document.createElement('div');
  glow.className = 'cursor-light-trail';
  glow.setAttribute('aria-hidden', 'true');
  document.body.appendChild(glow);
  let raf = 0, x = -300, y = -300;
  document.addEventListener('pointermove', event => {
    if (event.pointerType !== 'mouse') return;
    x = event.clientX; y = event.clientY;
    if (raf) return;
    raf = requestAnimationFrame(() => {
      glow.style.left = x + 'px';
      glow.style.top = y + 'px';
      raf = 0;
    });
  }, { passive: true });
})();

(function initPremiumTapFeedback() {
  document.addEventListener('pointerdown', event => {
    const target = event.target.closest('button, .link-card, .project-card, .photo-card, .primary');
    if (!target || target.disabled) return;
    target.classList.remove('premium-tap');
    void target.offsetWidth;
    target.classList.add('premium-tap');
    setTimeout(() => target.classList.remove('premium-tap'), 380);
  }, { passive: true });
})();

render();
